with base as (select *, cast(discount_pct as int) as discount_pct_int, substring(channel, 1, 4) as channel_prefix, coalesce(channel, 'DIRECT') as channel_clean from promotions where ends_on > date '2023-07-31'), latest as (select id, promo_code, discount_pct, channel_prefix from base qualify rank() over (partition by channel order by ends_on desc) = 1), scored as (select *, sum(discount_pct) over (partition by promo_code order by discount_pct, id rows between unbounded preceding and current row) as cumulative_discount_pct, lag(discount_pct, 1, 0) over (partition by promo_code order by discount_pct, id) as prev_discount_pct, dense_rank() over (order by discount_pct desc) as discount_pct_dense_rank from latest), remaining_keys as (select id, promo_code from scored except distinct select id, promo_code from promotions where ends_on > '2024-10-04'), verified as (select s.* from scored s join remaining_keys k on s.id = k.id and s.promo_code = k.promo_code), remaining_keys_2 as (select promo_code from verified except select promo_code from promotions where starts_on <= '2025-10-27'), reconciled as (select s.* from verified s join remaining_keys_2 k on s.promo_code = k.promo_code), summary as (select case when discount_pct >= 0.32 then 'LARGE' else 'SMALL' end as discount_pct_tier, count(distinct promo_code) as distinct_promo_codes, round(sum(discount_pct_dense_rank) / nullif(count(case when promo_code = 'WELCOME5' then 1 end), 0), 2) as discount_pct_dense_rank_per_welcome5, count_if(promo_code = 'WELCOME5') as welcome5_events from reconciled group by case when discount_pct >= 0.32 then 'LARGE' else 'SMALL' end having welcome5_events > 1) select discount_pct_tier, welcome5_events from summary;
